"""Sort Colors — Dutch National Flag.

Three regions grow at once: everything before `low` is 0, everything after
`high` is 2, and `mid` scans the unknown middle. A swap with `high` brings in
an unseen value, so `mid` must not advance in that branch.

Time: O(n)   Space: O(1)
"""
from typing import List


class Solution:
    def sortColors(self, nums: List[int]) -> None:
        low, mid, high = 0, 0, len(nums) - 1
        while mid <= high:
            if nums[mid] == 0:
                nums[low], nums[mid] = nums[mid], nums[low]
                low += 1
                mid += 1
            elif nums[mid] == 1:
                mid += 1
            else:
                nums[mid], nums[high] = nums[high], nums[mid]
                high -= 1
